"""Data models for transactions and blocks."""
from __future__ import annotations

import json
from dataclasses import dataclass

from . import crypto


@dataclass
class Transaction:
    sender: str
    recipient: str
    amount: int
    signature: str

    @property
    def message(self) -> bytes:
        return crypto.canonical_message(self.sender, self.recipient, self.amount)

    @property
    def tx_id(self) -> str:
        return crypto.compute_tx_id(self.message)

    def to_dict(self) -> dict:
        """JSON-safe representation used both for storage and API output."""
        return {
            "from": self.sender,
            "to": self.recipient,
            "amount": self.amount,
            "signature": self.signature,
            "tx_id": self.tx_id,
        }

    @classmethod
    def from_dict(cls, data: dict) -> "Transaction":
        return cls(
            sender=data["from"],
            recipient=data["to"],
            amount=int(data["amount"]),
            signature=data["signature"],
        )


def block_header_bytes(height: int, prev_hash: str, merkle: str) -> bytes:
    """Deterministic serialization of the fields covered by the block hash.

    No timestamp is included: a block with the same parent and the same ordered
    transactions must always hash identically.
    """
    header = {"height": height, "merkle_root": merkle, "prev_hash": prev_hash}
    return json.dumps(header, sort_keys=True, separators=(",", ":")).encode("utf-8")


def compute_block_hash(height: int, prev_hash: str, merkle: str) -> str:
    return crypto.sha256_hex(block_header_bytes(height, prev_hash, merkle))


@dataclass
class Block:
    height: int
    prev_hash: str
    merkle_root: str
    transactions: list[Transaction]
    block_hash: str

    @classmethod
    def create(
        cls, height: int, prev_hash: str, transactions: list[Transaction]
    ) -> "Block":
        ordered = sorted(transactions, key=lambda tx: tx.tx_id)
        merkle = crypto.merkle_root([tx.tx_id for tx in ordered])
        block_hash = compute_block_hash(height, prev_hash, merkle)
        return cls(
            height=height,
            prev_hash=prev_hash,
            merkle_root=merkle,
            transactions=ordered,
            block_hash=block_hash,
        )

    def to_dict(self) -> dict:
        return {
            "height": self.height,
            "prev_hash": self.prev_hash,
            "merkle_root": self.merkle_root,
            "block_hash": self.block_hash,
            "transactions": [tx.to_dict() for tx in self.transactions],
        }

    @classmethod
    def from_dict(cls, data: dict) -> "Block":
        return cls(
            height=int(data["height"]),
            prev_hash=data["prev_hash"],
            merkle_root=data["merkle_root"],
            block_hash=data["block_hash"],
            transactions=[Transaction.from_dict(t) for t in data["transactions"]],
        )

    def to_summary(self) -> dict:
        """Response shape for GET /v1/blocks/{height}."""
        return {
            "height": self.height,
            "block_hash": self.block_hash,
            "prev_hash": self.prev_hash,
            "merkle_root": self.merkle_root,
            "transaction_ids": [tx.tx_id for tx in self.transactions],
        }

"""Cryptographic helpers: Ed25519 verification, SHA-256 ids and Merkle roots."""
from __future__ import annotations

import hashlib
import json

from cryptography.exceptions import InvalidSignature
from cryptography.hazmat.primitives.asymmetric.ed25519 import Ed25519PublicKey


def canonical_message(sender: str, recipient: str, amount: int) -> bytes:
    """Deterministic byte representation of a transaction payload.

    The payload is serialized as compact JSON with sorted keys so the same
    (from, to, amount) triple always yields identical bytes on every client.
    """
    payload = {"amount": amount, "from": sender, "to": recipient}
    return json.dumps(payload, sort_keys=True, separators=(",", ":")).encode("utf-8")


def sha256_hex(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest()


def compute_tx_id(message: bytes) -> str:
    """SHA-256 hex digest of the canonical transaction message."""
    return sha256_hex(message)


def verify_signature(public_key_hex: str, message: bytes, signature_hex: str) -> bool:
    """Verify an Ed25519 signature (public key and signature are hex strings).

    Returns False for malformed hex or wrong key/signature lengths rather than
    raising, so callers can treat every verification failure uniformly.
    """
    try:
        public_bytes = bytes.fromhex(public_key_hex)
        signature_bytes = bytes.fromhex(signature_hex)
    except ValueError:
        return False
    if len(public_bytes) != 32 or len(signature_bytes) != 64:
        return False
    try:
        public_key = Ed25519PublicKey.from_public_bytes(public_bytes)
        public_key.verify(signature_bytes, message)
    except (InvalidSignature, ValueError):
        return False
    return True


# Merkle root of an empty transaction list; fixed so genesis blocks are identical.
EMPTY_MERKLE_ROOT = sha256_hex(b"")


def merkle_root(tx_ids: list[str]) -> str:
    """SHA-256 Merkle root of the given tx ids.

    Levels are built by hashing ``sha256(left + right)`` hex-string pairs;
    a lone odd node at a level is promoted by pairing it with itself.
    Callers normally pass ids already sorted ascending.
    """
    if not tx_ids:
        return EMPTY_MERKLE_ROOT
    level = list(tx_ids)
    while len(level) > 1:
        if len(level) % 2 == 1:
            level.append(level[-1])
        level = [
            sha256_hex((level[i] + level[i + 1]).encode("ascii"))
            for i in range(0, len(level), 2)
        ]
    return level[0]

"""Ledger business logic: submit transactions, mine blocks, query state.

Balance convention
------------------
The contract defines no minting endpoint, so every identity starts with a
fixed endowment (``initial_balance``, overridable via LEDGER_INITIAL_BALANCE).
An account's confirmed balance is::

    initial_balance + sum(confirmed amounts received) - sum(confirmed amounts sent)

An identity only becomes a *queryable account* once it appears in a confirmed
block; GET account before that returns 404. Balance checks at submission time
treat an identity that has never appeared on chain as holding the initial
endowment, otherwise the first transaction in an empty ledger could never be
accepted.
"""
from __future__ import annotations

from . import crypto
from .models import Block, Transaction
from .store import LedgerStore

DEFAULT_INITIAL_BALANCE = 1_000_000

REQUIRED_TX_FIELDS = ("from", "to", "amount", "signature")


class LedgerService:
    def __init__(self, store: LedgerStore, initial_balance: int = DEFAULT_INITIAL_BALANCE) -> None:
        self.store = store
        self.initial_balance = initial_balance

    # -- transactions -------------------------------------------------------

    def submit_transaction(self, payload: object) -> tuple[int, dict]:
        """Validate and enqueue a transaction. Returns (status, body)."""
        if not isinstance(payload, dict):
            return 400, {"error": "request body must be a JSON object"}
        for field in REQUIRED_TX_FIELDS:
            if field not in payload:
                return 400, {"error": f"missing field: {field}"}

        sender = payload["from"]
        recipient = payload["to"]
        amount = payload["amount"]
        signature = payload["signature"]

        if not isinstance(sender, str) or not sender:
            return 400, {"error": "field 'from' must be a non-empty string"}
        if not isinstance(recipient, str) or not recipient:
            return 400, {"error": "field 'to' must be a non-empty string"}
        # bool is a subclass of int: reject it and all non-int types explicitly.
        if not isinstance(amount, int) or isinstance(amount, bool) or amount <= 0:
            return 400, {"error": "field 'amount' must be a positive integer"}
        if not isinstance(signature, str) or not signature:
            return 400, {"error": "field 'signature' must be a non-empty string"}

        message = crypto.canonical_message(sender, recipient, amount)
        if not crypto.verify_signature(sender, message, signature):
            return 400, {"error": "invalid signature"}

        tx = Transaction(sender, recipient, amount, signature)
        with self.store.lock:
            if tx.tx_id in self.store.pending:
                return 409, {"error": "transaction already pending", "tx_id": tx.tx_id}
            if any(tx.tx_id == existing.tx_id for block in self.store.chain for existing in block.transactions):
                return 409, {"error": "transaction already confirmed", "tx_id": tx.tx_id}
            if self.available_balance(sender) < amount:
                return 400, {"error": "insufficient balance"}
            self.store.pending[tx.tx_id] = tx
            self.store.save()
        return 202, {"tx_id": tx.tx_id}

    # -- blocks -------------------------------------------------------------

    def mine_block(self) -> tuple[int, dict]:
        """Pack all pending transactions (ascending tx_id) into one block."""
        with self.store.lock:
            if not self.store.pending:
                return 409, {"error": "no pending transactions"}
            ordered = sorted(self.store.pending.values(), key=lambda tx: tx.tx_id)
            block = Block.create(
                height=self.store.next_height(),
                prev_hash=self.store.tip_hash(),
                transactions=ordered,
            )
            self.store.chain.append(block)
            for tx in ordered:
                self.store.pending.pop(tx.tx_id, None)
            self.store.save()
        return 201, {
            "height": block.height,
            "block_hash": block.block_hash,
            "merkle_root": block.merkle_root,
        }

    def get_block(self, height: object) -> tuple[int, dict]:
        try:
            height_int = int(height)  # type: ignore[arg-type]
            if str(height_int) != str(height).strip():
                raise ValueError
        except (TypeError, ValueError):
            return 404, {"error": "block not found"}
        with self.store.lock:
            if height_int < 0 or height_int >= len(self.store.chain):
                return 404, {"error": "block not found"}
            return 200, self.store.chain[height_int].to_summary()

    # -- accounts -----------------------------------------------------------

    def get_account(self, account: str) -> tuple[int, dict]:
        with self.store.lock:
            confirmed: list[str] = []
            for block in self.store.chain:
                for tx in block.transactions:
                    if tx.sender == account or tx.recipient == account:
                        confirmed.append(tx.tx_id)
            if not confirmed:
                return 404, {"error": "account not found"}
            return 200, {
                "account": account,
                "balance": self.confirmed_balance(account),
                "confirmed_transactions": confirmed,
            }

    def confirmed_balance(self, account: str) -> int:
        balance = self.initial_balance
        for block in self.store.chain:
            for tx in block.transactions:
                if tx.sender == account:
                    balance -= tx.amount
                if tx.recipient == account:
                    balance += tx.amount
        return balance

    def available_balance(self, account: str) -> int:
        """Confirmed balance minus amounts already committed in pending txs.

        Pending credits are deliberately not counted, so a sequence of
        submissions cannot spend money that has not been packed yet.
        """
        balance = self.confirmed_balance(account)
        for tx in self.store.pending.values():
            if tx.sender == account:
                balance -= tx.amount
        return balance

"""HTTP server exposing the ledger REST API using the Python standard library."""
from __future__ import annotations

import json
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from urllib.parse import unquote

from .service import LedgerService

MAX_BODY_BYTES = 1 << 20  # 1 MiB cap on request bodies


def build_handler(service: LedgerService) -> type[BaseHTTPRequestHandler]:
    """Create a handler class closed over the given ledger service."""

    class LedgerHandler(BaseHTTPRequestHandler):
        server_version = "VerifiableLedger/1.0"

        # -- helpers --------------------------------------------------------

        def _send_json(self, status: int, body: dict) -> None:
            data = json.dumps(body, ensure_ascii=False, sort_keys=True).encode("utf-8")
            self.send_response(status)
            self.send_header("Content-Type", "application/json; charset=utf-8")
            self.send_header("Content-Length", str(len(data)))
            self.end_headers()
            self.wfile.write(data)

        def _read_json(self) -> tuple[bool, object]:
            try:
                length = int(self.headers.get("Content-Length", "0"))
            except ValueError:
                return False, {"error": "invalid Content-Length"}
            if length <= 0:
                return False, {"error": "request body must be JSON"}
            if length > MAX_BODY_BYTES:
                return False, {"error": "request body too large"}
            raw = self.rfile.read(length)
            try:
                return True, json.loads(raw.decode("utf-8"))
            except (ValueError, UnicodeDecodeError):
                return False, {"error": "request body must be valid JSON"}

        # -- routing --------------------------------------------------------

        def do_POST(self) -> None:  # noqa: N802 (stdlib naming)
            path = self.path.split("?", 1)[0]
            if path == "/v1/transactions":
                ok, payload = self._read_json()
                if not ok:
                    self._send_json(400, payload)  # type: ignore[arg-type]
                    return
                status, body = service.submit_transaction(payload)
                self._send_json(status, body)
            elif path == "/v1/blocks":
                # A body is not required; drain one if present.
                if self.headers.get("Content-Length"):
                    self._read_json()
                status, body = service.mine_block()
                self._send_json(status, body)
            else:
                self._send_json(404, {"error": "not found"})

        def do_GET(self) -> None:  # noqa: N802 (stdlib naming)
            path = self.path.split("?", 1)[0]
            if path.startswith("/v1/blocks/"):
                height = unquote(path[len("/v1/blocks/") :])
                status, body = service.get_block(height)
                self._send_json(status, body)
            elif path.startswith("/v1/accounts/"):
                account = unquote(path[len("/v1/accounts/") :])
                if not account:
                    self._send_json(404, {"error": "account not found"})
                    return
                status, body = service.get_account(account)
                self._send_json(status, body)
            else:
                self._send_json(404, {"error": "not found"})

    return LedgerHandler


def serve(service: LedgerService, host: str, port: int) -> ThreadingHTTPServer:
    """Create and run the HTTP server (blocks until interrupted)."""
    httpd = ThreadingHTTPServer((host, port), build_handler(service))
    httpd.serve_forever()
    return httpd

"""Persistent storage: blockchain and pending transaction set (JSON file).

The whole state lives in one JSON file written atomically (temp file plus
``os.replace``), which is sufficient for a single-process ledger. A
re-entrant lock guards state so the threaded HTTP server serializes updates.
"""
from __future__ import annotations

import json
import os
import tempfile
import threading

from .models import Block, Transaction

# Previous hash of the genesis block.
GENESIS_PREV_HASH = "0" * 64


class LedgerStore:
    def __init__(self, path: str) -> None:
        self.path = path
        self.chain: list[Block] = []
        self.pending: dict[str, Transaction] = {}
        self._lock = threading.RLock()
        self.load()

    @property
    def lock(self) -> threading.RLock:
        return self._lock

    def load(self) -> None:
        """Load state from disk, creating a genesis block on first start."""
        if not os.path.exists(self.path):
            self.chain = [self.create_genesis()]
            self.pending = {}
            self.save()
            return
        with open(self.path, "r", encoding="utf-8") as fh:
            data = json.load(fh)
        self.chain = [Block.from_dict(b) for b in data.get("chain", [])]
        self.pending = {
            tx.tx_id: tx
            for tx in (Transaction.from_dict(t) for t in data.get("pending", []))
        }
        if not self.chain:
            self.chain = [self.create_genesis()]

    @staticmethod
    def create_genesis() -> Block:
        return Block.create(height=0, prev_hash=GENESIS_PREV_HASH, transactions=[])

    def save(self) -> None:
        """Atomically persist chain and pending transactions."""
        data = {
            "chain": [block.to_dict() for block in self.chain],
            "pending": [tx.to_dict() for tx in self.pending.values()],
        }
        directory = os.path.dirname(os.path.abspath(self.path)) or "."
        os.makedirs(directory, exist_ok=True)
        fd, tmp_path = tempfile.mkstemp(prefix=".ledger-", dir=directory)
        try:
            with os.fdopen(fd, "w", encoding="utf-8") as fh:
                json.dump(data, fh, ensure_ascii=False, sort_keys=True)
            os.replace(tmp_path, self.path)
        except BaseException:
            if os.path.exists(tmp_path):
                os.unlink(tmp_path)
            raise

    def tip_hash(self) -> str:
        return self.chain[-1].block_hash

    def next_height(self) -> int:
        return self.chain[-1].height + 1

"""Command line interface: send, mine, block, account subcommands.

The CLI talks to a running ledger server over HTTP and prints each response as
a single line of JSON with exactly the same field names as the HTTP API.

Signing a transaction locally is supported through ``send --signing-key``;
the key may be 32 raw hex bytes or ``@/path/to/ed25519-key.pem``. An already
produced signature can be passed instead with ``--from/--signature``.
"""
from __future__ import annotations

import argparse
import json
import os
import sys
import urllib.error
import urllib.request
from typing import Any

from . import crypto

DEFAULT_BASE_URL = os.environ.get("LEDGER_BASE_URL", "http://127.0.0.1:8080")


# -- HTTP helpers ------------------------------------------------------------


def _request(method: str, url: str, payload: dict | None) -> tuple[int, dict]:
    data = None
    headers = {"Accept": "application/json"}
    if payload is not None:
        data = json.dumps(payload, sort_keys=True).encode("utf-8")
        headers["Content-Type"] = "application/json"
    request = urllib.request.Request(url, data=data, headers=headers, method=method)
    try:
        with urllib.request.urlopen(request) as response:
            return response.status, json.loads(response.read().decode("utf-8"))
    except urllib.error.HTTPError as exc:
        try:
            body = json.loads(exc.read().decode("utf-8"))
        except (ValueError, UnicodeDecodeError):
            body = {"error": exc.reason}
        return exc.code, body
    except (urllib.error.URLError, OSError) as exc:
        return 0, {"error": f"cannot reach ledger server: {exc}"}


def _emit(status: int, body: dict) -> int:
    print(json.dumps(body, sort_keys=True, ensure_ascii=False))
    # 2xx responses are success; anything else (incl. connection failure) is 1.
    return 0 if 200 <= status < 300 else 1


# -- signing key handling ----------------------------------------------------


def _load_signing_key(spec: str):
    """Load an Ed25519 private key from raw hex or an ``@file`` (hex or PEM)."""
    from cryptography.hazmat.primitives import serialization

    if spec.startswith("@"):
        with open(spec[1:], "rb") as fh:
            material = fh.read()
    else:
        material = spec.encode("ascii")
    stripped = material.strip()
    if stripped.startswith(b"-----BEGIN"):
        key = serialization.load_pem_private_key(stripped, password=None)
    else:
        raw = bytes.fromhex(stripped.decode("ascii"))
        if len(raw) != 32:
            raise ValueError("signing key must be 32 raw bytes (64 hex chars)")
        from cryptography.hazmat.primitives.asymmetric.ed25519 import (
            Ed25519PrivateKey,
        )

        key = Ed25519PrivateKey.from_private_bytes(raw)
    from cryptography.hazmat.primitives.asymmetric.ed25519 import Ed25519PrivateKey

    if not isinstance(key, Ed25519PrivateKey):
        raise ValueError("signing key is not an Ed25519 private key")
    return key


def _public_key_hex(key) -> str:
    from cryptography.hazmat.primitives import serialization

    return key.public_key().public_bytes(
        serialization.Encoding.Raw, serialization.PublicFormat.Raw
    ).hex()


# -- subcommands -------------------------------------------------------------


def cmd_send(args: argparse.Namespace) -> int:
    if args.signing_key:
        try:
            key = _load_signing_key(args.signing_key)
        except (ValueError, OSError, TypeError) as exc:
            return _emit(400, {"error": f"invalid signing key: {exc}"})
        sender = _public_key_hex(key)
        message = crypto.canonical_message(sender, args.to, args.amount)
        signature = key.sign(message).hex()
    else:
        if not args.sender or not args.signature:
            return _emit(
                400,
                {"error": "provide either --signing-key or both --from and --signature"},
            )
        sender, signature = args.sender, args.signature

    payload = {
        "from": sender,
        "to": args.to,
        "amount": args.amount,
        "signature": signature,
    }
    status, body = _request("POST", f"{args.base_url}/v1/transactions", payload)
    return _emit(status, body)


def cmd_mine(args: argparse.Namespace) -> int:
    status, body = _request("POST", f"{args.base_url}/v1/blocks", {})
    return _emit(status, body)


def cmd_block(args: argparse.Namespace) -> int:
    status, body = _request(
        "GET", f"{args.base_url}/v1/blocks/{args.height}", None
    )
    return _emit(status, body)


def cmd_account(args: argparse.Namespace) -> int:
    quoted = urllib.request.quote(args.account, safe="")
    status, body = _request(
        "GET", f"{args.base_url}/v1/accounts/{quoted}", None
    )
    return _emit(status, body)


# -- argparse wiring ---------------------------------------------------------


def build_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(prog="ledger", description="Verifiable ledger CLI")
    parser.add_argument(
        "--base-url",
        default=DEFAULT_BASE_URL,
        help="ledger server URL (default: LEDGER_BASE_URL or %(default)s)",
    )
    sub = parser.add_subparsers(dest="command", required=True)

    p_send = sub.add_parser("send", help="submit a transaction")
    p_send.add_argument("--to", required=True, help="recipient account id")
    p_send.add_argument("--amount", required=True, type=int, help="integer amount")
    p_send.add_argument("--signing-key", help="sender Ed25519 private key: hex or @file (PEM/hex)")
    p_send.add_argument("--from", dest="sender", help="sender public key hex (with --signature)")
    p_send.add_argument("--signature", help="raw Ed25519 signature hex")
    p_send.set_defaults(func=cmd_send)

    p_mine = sub.add_parser("mine", help="pack pending transactions into a block")
    p_mine.set_defaults(func=cmd_mine)

    p_block = sub.add_parser("block", help="fetch a block by height")
    p_block.add_argument("height", help="block height (0 = genesis)")
    p_block.set_defaults(func=cmd_block)

    p_account = sub.add_parser("account", help="fetch an account")
    p_account.add_argument("account", help="account id (public key hex)")
    p_account.set_defaults(func=cmd_account)

    return parser


def main(argv: list[str] | None = None) -> int:
    parser = build_parser()
    args = parser.parse_args(argv)
    return args.func(args)


if __name__ == "__main__":
    sys.exit(main())

